// RenderFrameHostStateChanged: This method is invoked whenever one of the frames of a WebContents changes its
// |RenderFrameHost::GetLifecycleState()| i.e., when RenderFrameHost LifecycleState
// changes from |old_state| to |new_state|. The old LifecycleState that is being changed
// is |old_state| and the LifecycleState that it changes to is |new_state|. |old_state|
// and |new_state| are always different, i.e., a frame can't transition to the same
// state. This method allows code to react to RenderFrameHost LifecycleState changes.
// For example, to detect changes in the currently active document and perform different
// actions accordingly, like closing UI/resetting states, RenderFrameHostStateChanged is
// preferred instead of DidFinishNavigation. DidFinishNavigation does not guarantee that
// the old document will go away. Instead, it could enter the BackForwardCache and then
// become kActive later. Features that need to handle transitions like these should
// monitor LifecycleState changes instead. A particular document may change its
// LifecycleState and trigger RenderFrameHostStateChanged as part of being committed in
// a navigation, when another document replaces it by navigating in the same frame, in
// response to being detached from the DOM, or (with MPArch) as part of activating a
// prerendered page. When committing a cross-document, cross-RenderFrameHost navigation,
// navigation-related callbacks are dispatched in the following order: -
// RenderFrameHostStateChanged(new_frame, old_state, new_state) -
// RenderFrameHostChanged(old_frame, new_frame) - RenderFrameHostStateChanged(old_frame,
// old_state, new_state) - DidFinishNavigation(navigation_handle)
func (c *ObserverHooks) OnRenderFrameHostStateChanged(f func(tab WebContents, renderFrameHost RenderFrameHost, oldState RenderFrameHostLifecycleState, newState RenderFrameHostLifecycleState)) {
	c.hooks.subscribe(ObserverRenderFrameHostStateChanged)
	c.onRenderFrameHostStateChanged = append(c.onRenderFrameHostStateChanged, f)
}

// RenderViewDeleted: This method is invoked when a RenderViewHost of the WebContents is deleted. Note that
// this does not always happen when the WebContents starts to use a different
// RenderViewHost, as the old RenderViewHost might get just swapped out.
func (c *ObserverHooks) OnRenderViewDeleted(f func(tab WebContents, renderViewHost RenderViewHost)) {
	c.hooks.subscribe(ObserverRenderViewDeleted)
	c.onRenderViewDeleted = append(c.onRenderViewDeleted, f)
}

// RenderViewHostChanged: This method is invoked when a WebContents swaps its visible RenderViewHost with
// another one, possibly changing processes. The RenderViewHost that has been replaced
// is in |old_host|, which is nullptr if the old RVH was shut down.
func (c *ObserverHooks) OnRenderViewHostChanged(f func(tab WebContents, oldHost RenderViewHost, newHost RenderViewHost)) {
	c.hooks.subscribe(ObserverRenderViewHostChanged)
	c.onRenderViewHostChanged = append(c.onRenderViewHostChanged, f)
}

// RenderViewReady: This method is invoked when the `blink::WebView` of the current RenderViewHost is
// ready, e.g. because we recreated it after a crash.
func (c *ObserverHooks) OnRenderViewReady(f func(tab WebContents)) {
	c.hooks.subscribe(ObserverRenderViewReady)
	c.onRenderViewReady = append(c.onRenderViewReady, f)
}

// ResourceLoadComplete: This method is invoked when a resource associate with the frame |render_frame_host|
// has been loaded, successfully or not. |request_id| will only be populated for main
// frame resources. |original_url| is the unsanitized original URL of the resource
// request tracked by the browser process. |resource_load_info| comes directly from the
// renderer process. When `kSanitizeOriginalUrlDuringNavigation` is enabled,
// |resource_load_info.original_url| may be sanitized to be just the origin, while
// |original_url| is always the full URL.
func (c *ObserverHooks) OnResourceLoadComplete(f func(tab WebContents, renderFrameHost RenderFrameHost, requestId GlobalRequestID, originalUrl string, resourceLoadInfo ResourceLoadInfo)) {
	c.hooks.subscribe(ObserverResourceLoadComplete)
	c.onResourceLoadComplete = append(c.onResourceLoadComplete, f)
}

// SafeAreaConstraintChanged: This method is called when the safe area constraint changed.
func (c *ObserverHooks) OnSafeAreaConstraintChanged(f func(tab WebContents, hasConstraint bool)) {
	c.hooks.subscribe(ObserverSafeAreaConstraintChanged)
	c.onSafeAreaConstraintChanged = append(c.onSafeAreaConstraintChanged, f)
}

// SurfaceEmbedChildWebContentsAttached: Called when a SurfaceEmbed child WebContents is attached to its embedder.
// `inner_web_contents` is the child WebContents. `embedder_render_frame_host` is the
// outer document's RenderFrameHost that embeds it. NOTE: This API is intended only for
// a very specific, narrow use-case. Very few observers should need this. Do not use
// this unless you are specifically managing SurfaceEmbed relationships.
func (c *ObserverHooks) OnSurfaceEmbedChildWebContentsAttached(f func(tab WebContents, innerWebContents WebContents, embedderRenderFrameHost RenderFrameHost)) {
	c.hooks.subscribe(ObserverSurfaceEmbedChildWebContentsAttached)
	c.onSurfaceEmbedChildWebContentsAttached = append(c.onSurfaceEmbedChildWebContentsAttached, f)
}

// SurfaceEmbedChildWebContentsDetached: Called when a SurfaceEmbed child WebContents is detached from its parent.
// `inner_web_contents` is the child WebContents. NOTE: This API is intended only for a
// very specific, narrow use-case. Very few observers should need this. Do not use this
// unless you are specifically managing SurfaceEmbed relationships.
func (c *ObserverHooks) OnSurfaceEmbedChildWebContentsDetached(f func(tab WebContents, innerWebContents WebContents)) {
	c.hooks.subscribe(ObserverSurfaceEmbedChildWebContentsDetached)
	c.onSurfaceEmbedChildWebContentsDetached = append(c.onSurfaceEmbedChildWebContentsDetached, f)
}

// TitleWasSet: This method is invoked when the title of the WebContents is set.
func (c *ObserverHooks) OnTitleWasSet(f func(tab WebContents, entry NavigationEntry)) {
	c.hooks.subscribe(ObserverTitleWasSet)
	c.onTitleWasSet = append(c.onTitleWasSet, f)
}

// TitleWasSetForMainFrame: Invoked when the title is changed for any main frame in the WebContents (a primary
// main frame of a WebContents, a fenced frame or a MPArch guest).
func (c *ObserverHooks) OnTitleWasSetForMainFrame(f func(tab WebContents, renderFrameHost RenderFrameHost)) {
	c.hooks.subscribe(ObserverTitleWasSetForMainFrame)
	c.onTitleWasSetForMainFrame = append(c.onTitleWasSetForMainFrame, f)
}

// VibrationRequested: Called when WebContents received a request to vibrate the page.
func (c *ObserverHooks) OnVibrationRequested(f func(tab WebContents)) {
	c.hooks.subscribe(ObserverVibrationRequested)
	c.onVibrationRequested = append(c.onVibrationRequested, f)
}

// WasDiscarded: Called when WebContents has finished its discard operation.
func (c *ObserverHooks) OnWasDiscarded(f func(tab WebContents)) {
	c.hooks.subscribe(ObserverWasDiscarded)
	c.onWasDiscarded = append(c.onWasDiscarded, f)
}

// WebAuthnAssertionRequestSucceeded: Called when the given `render_frame_host` successfully completes a Web Authentication
// API assertion request.
func (c *ObserverHooks) OnWebAuthnAssertionRequestSucceeded(f func(tab WebContents, renderFrameHost RenderFrameHost)) {
	c.hooks.subscribe(ObserverWebAuthnAssertionRequestSucceeded)
	c.onWebAuthnAssertionRequestSucceeded = append(c.onWebAuthnAssertionRequestSucceeded, f)
}

// WebContentsDestroyed: Invoked when the WebContents is being destroyed. Gives subclasses a chance to
// cleanup. After the whole loop over all WebContentsObservers has been finished,
// web_contents() returns nullptr. Do not use this method. It is invoked half-way
// through the destructor of WebContentsImpl and using it often results in crashes or
// surprising behavior. Conceptually, this is only necessary by objects that depend on,
// but outlive the WebContents. These objects should instead coordinate with the owner
// of the WebContents which is responsible for destroying the WebContents.
func (c *ObserverHooks) OnWebContentsDestroyed(f func(tab WebContents)) {
	c.hooks.subscribe(ObserverWebContentsDestroyed)
	c.onWebContentsDestroyed = append(c.onWebContentsDestroyed, f)
}

